body.usercss:

        /*Footer*/

        .commentRow_info {
            background: #F1F1F1;
            padding: 5px 10px;
            font-size: 0.9em;
        }

        .commentRow_name {
            padding-top: 4px;
            width: 200px;
            float: left;
        }

        .commentRow_content {
            overflow-x: auto;
            padding: 5px 10px;
        }

        .commentRow_buttonBox {
            margin-left: calc(100% - 210px);
        }

        .commentRow_vault {
            float: left;
            margin-right: 30px;
            background: center / cover url(/resource/design/imgs/grid/CORRECT_ACCEPT.png);
            padding: 10px;
            border: none;
            margin-top: 5px;
        }

        .commentRow_vault_empty {
            float: left;
            margin-right: 30px;
            padding: 10px;
            border: none;
            background-size: 16px;
            background-color: transparent;
        }

        .commentRow_Date {
            font-weight: 500;
            float: left;
            padding-top: 4px;
        }

        .delButton {
            color: darkslategray;
            margin-left: 28px;
            border: 0;
            outline: 0;
            padding-left : 10px; 
            background-color: rgba(241, 241, 241, 0);
            font-size: 20px;
        }

        div.sepoaux_component_inner_wrapper.sepoaux_button_inner {
            padding-left: 23px;
        }

        div.sepoaux_component_inner_wrapper.sepoaux_button_inner.sepoaux_wrapper_style_halign_right {
            padding-right: 6px;
        }

        #REPLY_TITLE {
            cursor: auto;
        }

        font-size: 12pt !important;
        }

        .mce-tinymce .mce-statusbar {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
        }

        .mce-container iframe {
            border: 1px solid rgba(0, 0, 0, 0.2) !important;
        }

        .container_div {
        	border: 1px solid #DDDDDD;
        	width : 1140px;
        	display: flex;
        	flex-direction: column;
        	justify-content: center;
        }

        .lable_div {
        	display: flex;
        	justify-content: start;
        	padding-left: 10px;
        	align-items: center;
        	height: 40px;
        	margin-bottom: 16px;
        }

        .label_a {
        	text-decoration: none; 
        	color: inherit;
        	line-height: 39px;
        	display: block;
        	width : 100%;
        	height: 100%;
        	margin-top: 20px;
        }

        .label_a:hover {
	       	 color: skyblue;
	       	 font-weight: bold;
        }

